// Composition approach: NotificationService depends on interface
public interface MessageSender {
    void send(String recipient, String message);
}

@Service
public class NotificationService {
    private final MessageSender sender;  // composed collaborator

    public NotificationService(MessageSender sender) {
        this.sender = sender;  // injected via constructor
    }

    public void notifyUser(String userId, String alert) {
        sender.send(userId, alert);  // delegate to collaborator
    }
}

// In production, inject EmailSender; in tests, inject mock
@Test
void testNotification() {
    var mockSender = mock(MessageSender.class);
    var service = new NotificationService(mockSender);
    service.notifyUser("user123", "Payment received");
    verify(mockSender).send("user123", "Payment received");
}

// Original parent class
class Counter {
    private int count = 0;

    public void add(int value) {
        count += value;
    }

    public void addAll(List<Integer> values) {
        for (int v : values) {
            add(v);  // delegates to add() for each value
        }
    }
}

// Subclass overrides add() to track how many times it's called
class InstrumentedCounter extends Counter {
    private int addCount = 0;

    @Override
    public void add(int value) {
        addCount++;  // count each add call
        super.add(value);
    }

    public int getAddCount() { return addCount; }
}

// Now parent refactors addAll() to be more efficient
// New parent implementation:
public void addAll(List<Integer> values) {
    count += values.stream().mapToInt(Integer::intValue).sum();  // no longer calls add()
}

